from base import *
inner = '<div style="display:flex;gap:10px;justify-content:center">'+''.join(f'<div class="tile" style="width:110px;height:90px"><div class="q" style="font-size:11px">{a}</div><div style="font-size:14px;font-weight:600;margin-top:4px">{b}</div></div>' for a,b in [("NOW PLAYING","Paused"),("TIMER","12:34"),("SHELF","3 items")])+'</div><div style="display:flex;justify-content:center;gap:6px;margin-top:14px"><span class="dot" style="background:rgba(255,255,255,.25)"></span><span class="dot" style="background:#fff"></span><span class="dot" style="background:rgba(255,255,255,.25)"></span></div><div class="note" style="text-align:center">← &nbsp;→ &nbsp;also turn the page (alongside ↑ ↓ and the dots)</div>'
body = cap("Open notch · Home page 2 of 3") + opened(inner, h=210, tabs='<span>♫</span><span>▤</span><span>⏱</span><span>▦</span>')
open("m19.html","w").write(page("Home: Left and Right arrows turn the page","Up/Down already do; the horizontal arrows match how the pages lie.",body))
